const pipe = (...fns) => (x) => fns.reduce((v, f) => f(v), x);
const compose = (...fns) => (x) => fns.reduceRight((v, f) => f(v), x);

const wrap = (mark) => (text) => mark + text + mark;
const shout = (text) => text.toUpperCase() + "!";

console.log(pipe(wrap("*"), shout)("hi"));
console.log(compose(wrap("*"), shout)("hi"));
console.log(compose(pipe(shout, shout), wrap("_"))("ok"));
